_ZI_LINKS: dict[str, str] | None = None


def _zi_links() -> dict[str, str]:
    global _ZI_LINKS
    if _ZI_LINKS is None:
        _ZI_LINKS = {}
        import os
        paths = ["/usr/share/zoneinfo/tzdata.zi"]
