def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        if hours == 0:
            return "Etc/UTC"
        # POSIX Etc names invert the sign
        return f"Etc/GMT{'+' if m.group(1) in '-\\u2212' else '-'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    if tz in _zi_links():
        target = _zi_links()[tz]
        return "Etc/UTC" if target in ("UTC", "GMT") else target
    return tz


_SUPPORTED = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}


def _locale(loc: str) -> str:
    base = re.split(r"[.@]", loc, maxsplit=1)[0].replace("_", "-")
    parts = base.split("-")
    lang = parts[0].lower()
    tag = lang + ("-" + parts[1].upper() if len(parts) > 1 and parts[1] else "")
    if tag in _SUPPORTED:
        return tag
    return lang if lang in _SUPPORTED else "en-US"


_ZERO = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
NBSP = "\\u00a0"
# locale: (decimal, group, code before)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True), "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True), "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _round(value: str, currency: str) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-_digits(currency)), rounding=ROUND_HALF_EVEN)


def _group(ip: str, locale: str, sep: str) -> str:
    if locale == "es" and len(ip) <= 4:
        return ip
    if locale == "en-IN" and len(ip) > 3:
        head, tail = ip[:-3], ip[-3:]
        pieces = []
        while len(head) > 2:
            pieces.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pieces.insert(0, head)
        return sep.join(pieces + [tail])
    pieces = []
    while len(ip) > 3:
        pieces.insert(0, ip[-3:])
        ip = ip[:-3]
    return sep.join([ip] + pieces)


def _text(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, before = _STYLE[locale]
    n = _digits(currency)
    neg = value < 0
    s = f"{abs(value):.{n}f}"
    ip, _, fp = s.partition(".")
    num = _group(ip, locale, grp) + (dec + fp if n else "")
    if neg:
        num = "-" + num
    return f"{currency}{NBSP}{num}" if before else f"{num}{NBSP}{currency}"


